// @vitest-environment node
// libsodium's string encoding under jsdom yields a Uint8Array from jsdom's realm, which
// secretstream rejects ("unsupported input type"); browsers and Node have one realm.
/**
 * Chunked file bodies (`agent_docs/chunked-file-encryption.md`): NEB1, the Photos-chunked shape,
 * and the v0 dispatch beside them.
 *
 * `fixtures/chunked_file_vectors.json` is the canonical vector set — generated by
 * `scripts/generate-chunked-file-vectors.mjs`, an independent implementation over libsodium — and
 * every other client vendors a copy of it. Opening each case here and there is what keeps them able
 * to read each other's files.
 */

import { createHash } from 'node:crypto';
import { describe, it, expect, beforeAll } from 'vitest';
import {
  initSodium,
  generateFileKey,
  encryptFile,
  decryptFile,
  encryptFileNeb1,
  decryptNeb1,
  decryptPhotosChunked,
  chunkSizeFromMetadata,
  encryptMetadata,
  decryptMetadata,
  ChunkedHeaderError,
  ChunkedAuthError,
  NEB1_MIN_CHUNK_SIZE,
  NEB1_MAX_CHUNK_SIZE,
} from '../crypto';
import vectors from './fixtures/chunked_file_vectors.json';

beforeAll(async () => {
  await initSodium();
});

const fromB64 = (s: string) => new Uint8Array(Buffer.from(s, 'base64'));
const sha256 = (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex');
const dek = fromB64(vectors.dek);
const plaintextOf = (length: number) => {
  const bytes = new Uint8Array(length);
  for (let i = 0; i < length; i++) bytes[i] = (i * 7 + 3) & 0xff;
  return bytes;
};

describe('the canonical chunked-file vectors', () => {
  for (const c of vectors.cases as { name: string; shape: string; length: number; chunkSize?: number; sha256: string; ciphertext: string }[]) {
    it(`opens "${c.name}"`, () => {
      const plain = decryptFile(fromB64(c.ciphertext), dek, { chunkSize: c.chunkSize });
      expect(plain.length).toBe(c.length);
      expect(sha256(plain)).toBe(c.sha256);
    });
  }

  it('opens a 1 MiB Photos body with no metadata at all', () => {
    const c = vectors.cases.find((x) => x.name === 'photos-1mib')!;
    expect(sha256(decryptFile(fromB64(c.ciphertext), dek))).toBe(c.sha256);
  });

  it('opens a single-chunk Photos body as the v0 it is byte for byte', () => {
    const c = vectors.cases.find((x) => x.name === 'photos-single-is-v0')!;
    expect(sha256(decryptFile(fromB64(c.ciphertext), dek))).toBe(c.sha256);
  });

  for (const r of vectors.rejected as { name: string; ciphertext: string; chunkSize?: number; dek?: string }[]) {
    it(`rejects "${r.name}"`, () => {
      const key = r.dek ? fromB64(r.dek) : dek;
      expect(() => decryptFile(fromB64(r.ciphertext), key, { chunkSize: r.chunkSize })).toThrow();
      // Without its metadata too: the 1 MiB retry must not rescue a damaged body.
      expect(() => decryptFile(fromB64(r.ciphertext), key)).toThrow();
    });
  }
});

describe('NEB1', () => {
  const sizesFor = (C: number) => [0, 1, C - 1, C, C + 1, 2 * C, 2 * C + 1];

  for (const C of [NEB1_MIN_CHUNK_SIZE, 65536]) {
    for (const size of sizesFor(C)) {
      it(`round-trips ${size} bytes at chunkSize ${C}`, () => {
        const key = generateFileKey();
        const plain = plaintextOf(size);
        const blob = encryptFileNeb1(plain, key, C);
        expect(blob.length).toBe(44 + size + 17 * Math.max(1, Math.ceil(size / C)));
        expect(decryptFile(blob, key)).toEqual(plain);
      });
    }
  }

  it('round-trips at the largest chunk size', () => {
    const key = generateFileKey();
    const plain = plaintextOf(NEB1_MAX_CHUNK_SIZE + 3);
    expect(sha256(decryptNeb1(encryptFileNeb1(plain, key, NEB1_MAX_CHUNK_SIZE), key))).toBe(sha256(plain));
  });

  it('refuses to write a chunk size outside the accepted range', () => {
    const key = generateFileKey();
    expect(() => encryptFileNeb1(plaintextOf(10), key, NEB1_MIN_CHUNK_SIZE - 1)).toThrow(RangeError);
    expect(() => encryptFileNeb1(plaintextOf(10), key, NEB1_MAX_CHUNK_SIZE + 1)).toThrow(RangeError);
  });

  it('reports a malformed header as structural and a tampered body as authentication', () => {
    const key = generateFileKey();
    const blob = encryptFileNeb1(plaintextOf(10000), key, 4096);
    const badVersion = blob.slice(); badVersion[4] = 0x09;
    expect(() => decryptNeb1(badVersion, key)).toThrow(ChunkedHeaderError);
    const tampered = blob.slice(); tampered[200] ^= 0xff;
    expect(() => decryptNeb1(tampered, key)).toThrow(ChunkedAuthError);
  });

  it('never falls through to v0 after an authentication failure', () => {
    const key = generateFileKey();
    const tampered = encryptFileNeb1(plaintextOf(10000), key, 4096);
    tampered[tampered.length - 1] ^= 0x01;
    expect(() => decryptFile(tampered, key)).toThrow(ChunkedAuthError);
  });
});

describe('the Photos-chunked shape', () => {
  it('honours the metadata chunk size', () => {
    const c = vectors.cases.find((x) => x.name === 'photos-multi')!;
    expect(sha256(decryptPhotosChunked(fromB64(c.ciphertext), dek, 256))).toBe(c.sha256);
  });

  it('refuses an absurd chunk size rather than allocating for it', () => {
    const c = vectors.cases.find((x) => x.name === 'photos-multi')!;
    expect(() => decryptPhotosChunked(fromB64(c.ciphertext), dek, NEB1_MAX_CHUNK_SIZE + 1)).toThrow(ChunkedAuthError);
  });

  it('reads the chunk size out of decrypted metadata', () => {
    expect(chunkSizeFromMetadata({ name: 'a.mov', mimeType: 'video/quicktime', chunkSize: 1048576 })).toBe(1048576);
    expect(chunkSizeFromMetadata({ name: 'a.jpg', mimeType: 'image/jpeg' })).toBeUndefined();
    expect(chunkSizeFromMetadata({ chunkSize: '1048576' })).toBeUndefined();
    expect(chunkSizeFromMetadata(null)).toBeUndefined();
  });
});

describe('v0 is unchanged', () => {
  it('still round-trips byte for byte', () => {
    const key = generateFileKey();
    for (const size of [0, 1, 4096, 2 * 1024 * 1024 + 3]) {
      const plain = plaintextOf(size);
      expect(decryptFile(encryptFile(plain, key), key)).toEqual(plain);
    }
  });

  it('still carries metadata', () => {
    const key = generateFileKey();
    expect(decryptMetadata(encryptMetadata({ name: 'x', mimeType: 'text/plain' }, key), key))
      .toEqual({ name: 'x', mimeType: 'text/plain' });
  });

  it('fails a wrong key with the v0 error, not a chunked one', () => {
    const blob = encryptFile(plaintextOf(3 * 1024 * 1024), generateFileKey());
    expect(() => decryptFile(blob, generateFileKey())).toThrow(/invalid ciphertext or key/);
  });
});
